// The profile handlers (l6-accounts 8.1): GET /profile serves the CALLER's
// resolved identity — pure delegation to identity, zero viewer/visibility
// logic (the profile is about the principal's own facts, never library
// visibility; viewerFor is not consulted). PUT /profile/prefs replaces the
// caller's per-user preference document whole (identity stores it verbatim —
// the User Prefs passthrough discipline; the env-provided watch defaults
// stay the fallback for any knob the document carries no override for, and
// they keep being served by GET /watch-defaults — they are env config, never
// profile state, so this endpoint never serves them).
//
// KIND MAPPING (decided and documented — the Principal is the credential the
// auth chain 7.1 resolved, and it carries no credential-kind fact, so the
// kinds key on the principal's USER-BACKEDNESS):
//   - env-admin principal (RoleAdmin, UserID 0)  → kind "admin".
//   - ANY user-backed principal (UserID > 0 — a login session, an
//     admin-role session, or a device bound to a user) → kind "user" with
//     that user's facts: user_id, name (display_name, falling back to the
//     username when the display name is empty), the users.role literal,
//     the user's live groups, and the stored prefs document.
//   - everything else (an unbound device: RoleClient, UserID 0) → kind
//     "device": no user facts — name and role are the fixed principal
//     facts ("device" / "client"), groups are empty, prefs is null (a
//     device has no preference surface).
//
// The served role is the users.role literal for kind "user" ("user" |
// "admin" — an admin-role session serves "admin"), "admin" for the env
// admin, "client" for a device (the Role constants' lower-snake literals).
// The env admin's prefs is "{}" — the empty override document: every knob
// falls through to the env defaults, which is exactly the env-admin
// posture; a device's prefs is null — no document exists at all.

// profile kinds — the wire `kind` literal set (design wire contract).
const (
	profileKindAdmin  = "admin"
	profileKindUser   = "user"
	profileKindDevice = "device"
)

// profileGroup is one group entry of the profile wire shape: {id, name} —
// the member facts only, never a group's doc document (that is the admin
// surfaces' 9.x wire, not the caller's own profile).
type profileGroup struct {
	ID   int64  `json:"id"`
	Name string `json:"name"`
}

// profileResponse is the GET /profile wire shape: {kind, user_id?, name,
// role, groups, prefs, debug?}. user_id is omitted for the kinds with no
// backing user (admin, device); prefs is a RawMessage so each user's stored
// document crosses the wire byte-verbatim. Debug is the paired device's
// telemetry gate (android-tv-app 3.1), carried on the device kind only and
// omitted while false (omitempty — the admin and user kinds' answers are
// byte-unchanged by the field's existence).
type profileResponse struct {
	Kind   string          `json:"kind"`
	UserID int64           `json:"user_id,omitempty"`
	Name   string          `json:"name"`
	Role   string          `json:"role"`
	Groups []profileGroup  `json:"groups"`
	Prefs  json.RawMessage `json:"prefs"`
	Debug  bool            `json:"debug,omitempty"`
}

// profilePrefsRaw renders a stored prefs document for the wire. The empty
// document (what Create plants) serializes as the empty object — an empty
// RawMessage would break the JSON body, and "{}" is also its truthful
// reading: no overrides, the env defaults answer.
func profilePrefsRaw(prefs string) json.RawMessage {
	if strings.TrimSpace(prefs) == "" {
		return json.RawMessage("{}")
	}
	return json.RawMessage(prefs)
}

// profile reads the caller's identity: GET /api/v1/profile — authenticated
// (browse group; every principal kind has a profile). See the file comment
// for the kind mapping and the served facts per kind. A user-backed
// principal whose user row is GONE (a bound device can dangle — device
// credential rows survive their user's delete cascade; a session cannot,
// the cascade kills it) answers 404: the identity the credential names no
// longer exists (the repo's wrapped sql.ErrNoRows → 404 convention —
// decided and documented; the middleware never re-checks a device binding).
//
// @Summary     Serve the caller's resolved identity
// @Tags        profile
// @ID          profile-get
// @Router      /profile [get]
// @Success     200 {object} profileResponse
// @Failure     401 {object} errorBody
// @Failure     404 {object} errorBody "the credential's bound user no longer exists"
// @Failure     500 {object} errorBody
// @Failure     503 {object} errorBody
func (a *app) profile(w http.ResponseWriter, r *http.Request) {
	// The one raw-principal read outside the auth seam files, through
	// middleware.go's documented requestPrincipal accessor: the profile's
	// DOMAIN is the principal's own facts — authority still rides
	// viewerFor's stashed Viewer everywhere else, and nothing here derives
	// visibility from p.
	p, ok := requestPrincipal(r)
	if !ok {
		// Unreachable behind the browse group's authN; fail closed.
		writeError(w, http.StatusUnauthorized, "unauthenticated",
			"missing or invalid admin token", false)
		return
	}
	switch {
	case p.IsAdmin() && p.UserID == 0:
		writeJSON(w, http.StatusOK, profileResponse{
			Kind:   profileKindAdmin,
			Name:   "admin",
			Role:   "admin",
			Groups: []profileGroup{},
			Prefs:  json.RawMessage("{}"),
		})
	case p.UserID > 0:
		idsvc, ok := a.identityService()
		if !ok {
			writeError(w, http.StatusServiceUnavailable, "unavailable",
				"profile endpoint disabled", false)
			return
		}
		u, err := idsvc.UserByID(r.Context(), p.UserID)
		if err != nil {
			a.profileIdentityError(w, err)
			return
		}
		groups, err := idsvc.UserGroups(r.Context(), p.UserID)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
			return
		}
		out := make([]profileGroup, len(groups))
		for i, g := range groups {
			out[i] = profileGroup{ID: g.ID, Name: g.Name}
		}
		name := u.DisplayName
		if name == "" {
			name = u.Username
		}
		writeJSON(w, http.StatusOK, profileResponse{
			Kind:   profileKindUser,
			UserID: u.ID,
			Name:   name,
			Role:   u.Role,
			Groups: out,
			Prefs:  profilePrefsRaw(u.Prefs),
		})
	default:
		// The unbound device (RoleClient, UserID 0) — today's principal
		// with no user facts behind it. The device's debug telemetry gate
		// (android-tv-app 3.1) rides the credential row, not the Principal:
		// re-read the credential through the SAME lookup the auth chain's
		// device leg used (the bearer's hash — never a second derivation of
		// anything visibility-shaped). A store failure is a real failure →
		// 500 (fail-fast, like every other read); a miss between the
		// middleware and here is a mid-request revocation — debug-off is
		// then the only truthful answer.
		tok, err := a.deps.Store.LookupDeviceCredentialByHash(r.Context(),
			hashBearerToken(bearerCredentials(r.Header.Get("Authorization"))))
		if err != nil && !errors.Is(err, sql.ErrNoRows) {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
			return
		}
		writeJSON(w, http.StatusOK, profileResponse{
			Kind:   profileKindDevice,
			Name:   "device",
			Role:   string(RoleClient),
			Groups: []profileGroup{},
			Prefs:  json.RawMessage("null"),
			Debug:  err == nil && tok.Debug,
		})
	}
}

// putProfilePrefs replaces the CALLER's per-user preference document whole:
// PUT /api/v1/profile/prefs — the body IS the document (opaque JSON,
// validated only to BE a JSON object; identity stores it verbatim and the
// next GET /profile serves it back byte-for-byte). Never merged with the
// previous document — a PUT is the whole replacement.
//
// The refusal law (decided and documented): a principal with NO user
// backing (UserID 0 — the env admin token or an unbound device) answers
// 409 conflict, because there is no per-user document behind that
// credential to configure — the env admin's defaults are env config, not
// profile state, and a device has no preference surface. 204 on success.
//
// @Summary     Replace the caller's preference document
// @Tags        profile
// @ID          profile-put-prefs
// @Router      /profile/prefs [put]
// @Param       body body object true "the whole preference document (JSON object)"
// @Success     204 "document replaced"
// @Failure     400 {object} errorBody "malformed body, or not a JSON object"
// @Failure     401 {object} errorBody
// @Failure     404 {object} errorBody "the credential's bound user no longer exists"
// @Failure     409 {object} errorBody "principal carries no per-user document (env admin, unbound device)"
// @Failure     500 {object} errorBody
// @Failure     503 {object} errorBody
func (a *app) putProfilePrefs(w http.ResponseWriter, r *http.Request) {
	p, ok := requestPrincipal(r)
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthenticated",
			"missing or invalid admin token", false)
		return
	}
	if p.UserID == 0 {
		// Env admin and unbound device alike: no per-user document exists
		// behind this credential (the law is USER-BACKEDNESS, not role —
		// an admin-role session has UserID > 0 and configures its own doc).
		writeError(w, http.StatusConflict, "conflict",
			"this principal carries no per-user preference document", false)
		return
	}
	idsvc, ok := a.identityService()
	if !ok {
		writeError(w, http.StatusServiceUnavailable, "unavailable",
			"profile endpoint disabled", false)
		return
	}
	raw, err := io.ReadAll(r.Body)
	if err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "unreadable request body", false)
		return
	}
	// Validate ONLY the shape: the document must be one JSON object. Its
	// contents are opaque — identity stores the raw bytes verbatim and
	// parses nothing (the User Prefs passthrough discipline). null is not
	// an object (Unmarshal leaves the map nil without error — refused).
	var doc map[string]any
	if err := json.Unmarshal(raw, &doc); err != nil || doc == nil {
		writeError(w, http.StatusBadRequest, "bad_request",
			"prefs must be a JSON object", false)
		return
	}
	// The caller's document — keyed by the credential's own user, never a
	// request parameter (a principal writes only its own profile).
	u, err := idsvc.UserByID(r.Context(), p.UserID)
	if err != nil {
		a.profileIdentityError(w, err)
		return
	}
	if err := idsvc.SetPrefs(r.Context(), u.Username, string(raw)); err != nil {
		a.profileIdentityError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

// profileIdentityError maps an identity read/write failure on the caller's
// own user row: the wrapped sql.ErrNoRows unknown-user shape is the 404
// (the dangling-credential case the GET documents), everything else 500s.
func (a *app) profileIdentityError(w http.ResponseWriter, err error) {
	if errors.Is(err, sql.ErrNoRows) {
		writeError(w, http.StatusNotFound, "not_found",
			"the credential's bound user no longer exists", false)
		return
	}
	writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
}
